import React, { useState } from 'react';
import ConversationChunk from './ConversationChunk';
import { getCyberpunkColors } from '../Analysis/ComplaintTrackingChart';

const ConversationDetail = ({ analyzedData }) => {
  const [expandedChunk, setExpandedChunk] = useState(null);
  const colors = getCyberpunkColors();

  // Handle the expansion change of a chunk
  const handleExpandChange = (chunkId) => () => {
    setExpandedChunk(expandedChunk === chunkId ? null : chunkId);
  };

  // Exit early if no data
  if (!analyzedData || !analyzedData.chunks || analyzedData.chunks.length === 0) {
    return (
      <div className="w-full p-3 text-center" style={{ color: colors.neon.darkGreen }}>
        <p className="font-mono text-sm">// NO CONVERSATION DATA AVAILABLE //</p>
      </div>
    );
  }

  return (
    <div className="w-full">
      <div className="mb-3 text-center font-mono text-xs" style={{ color: colors.neon.darkGreen }}>
        <p>// EXPAND CHUNKS TO VIEW CONVERSATION DETAILS //</p>
      </div>
      
      <div className="space-y-2">
        {analyzedData.chunks.map((chunk, index) => (
          <ConversationChunk 
            key={chunk.id || index}
            chunk={chunk}
            index={index}
            expanded={expandedChunk === (chunk.id || index)}
            onChange={handleExpandChange(chunk.id || index)}
          />
        ))}
      </div>
    </div>
  );
};

export default ConversationDetail;
